const lead = $node['Webhook Lead Qualification'].json.body;
const dncRecords = $input.all();
const isDNC = dncRecords.length > 0 && dncRecords[0].json && dncRecords[0].json.phone;

const phone = (lead.phone || '').trim();
const phoneValid = phone.length >= 10 && (phone.startsWith('+91') || phone.startsWith('91') || phone.length === 10);
const callAttempts = parseInt(lead.call_attempts || 0, 10);
const maxAttempts = parseInt(lead.max_attempts || 3, 10);

if (isDNC) {
  return [{ json: { qualified: false, status: 'DO_NOT_CALL', reason: 'Phone listed in DNC suppression database' } }];
}
if (!phoneValid) {
  return [{ json: { qualified: false, status: 'INVALID', reason: 'Phone number format invalid' } }];
}
if (callAttempts >= maxAttempts) {
  return [{ json: { qualified: false, status: 'SKIPPED', reason: `Max call attempts (${maxAttempts}) reached` } }];
}

return [{ json: { qualified: true, status: 'READY_TO_CALL', reason: 'Eligible for AI Voice Outbound Call' } }];
